node <<'NODE'
const fs=require('fs'), path=require('path'), crypto=require('crypto'), cp=require('child_process');
const dir='.flow/artifacts/fn-109-gomad-deepen-modules-and-tool-interfaces/task-25';
const read=p=>fs.readFileSync(p,'utf8'), hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const raw=read(dir+'/root-fast.log');
const observed=[...raw.matchAll(/^(tools\/gomad3\/[^\n:]+):(\d+):(\d+): (.*) \((\w+)\)$/gm)].map(m=>({path:m[1],line:+m[2],column:+m[3],message:m[4],linter:m[5],owner:path.dirname(m[1])}));
const retained=JSON.parse(read(dir+'/../task-24/gomad-findings.json'));
const canon=a=>a.map(x=>JSON.stringify(x)).sort();
const equal=JSON.stringify(canon(observed))===JSON.stringify(canon(retained));
const receipts=fs.readdirSync(dir).filter(p=>p.endsWith('.receipt.json')).map(p=>{const r=JSON.parse(read(dir+'/'+p));return {path:p,sha256:hash(dir+'/'+p),command:r.command,exit:r.exit_code,elapsed_seconds:r.elapsed_seconds,stability_before:r.stability_before_exit,stability_after:r.stability_after_exit,source_freeze:r.source_freeze,log:r.log,log_sha256:hash(dir+'/'+r.log)};});
const freezes=Object.fromEntries(['old-source','draft-characterization-source','characterization-source','final-source'].map(n=>[n,read(dir+'/'+n+'.sha256').trim().split('\n').map(l=>l.split(/  /))]));
const oldhash=crypto.createHash('sha256').update(cp.execFileSync('git',['show','HEAD:tools/gomad3sim/controller.go'])).digest('hex');
const freezeChanges={};for(const n of ['draft-characterization-source','characterization-source','final-source']){const previous=Object.fromEntries(freezes[n==='draft-characterization-source'?'old-source':n==='characterization-source'?'draft-characterization-source':'characterization-source'].map(([h,p])=>[p,h]));freezeChanges[n]=freezes[n].filter(([h,p])=>previous[p]!==h).map(([h,p])=>p);}
const go=cp.execFileSync('/home/agent/go/pkg/mod/golang.org/toolchain@v0.0.1-go1.27.1.linux-arm64/bin/go',['version'],{encoding:'utf8'}).trim();
const result={observed_count:observed.length,retained_count:retained.length,exact_entries_match:equal,owner_count:new Set(observed.map(x=>x.owner)).size,receipts,source_freeze_hashes:Object.fromEntries(Object.keys(freezes).map(n=>[n+'.sha256',hash(dir+'/'+n+'.sha256')])),freeze_changes:freezeChanges,old_controller_head_hash:oldhash,old_controller_freeze_hash:freezes['old-source'].find(([,p])=>p==='tools/gomad3sim/controller.go')[0],go_version:go,root_scope_markers:raw.split('\n').filter(l=>/lintcode|0 issues\.|419 issues|go vet|errortype|Entering|Leaving/.test(l))};
console.log(JSON.stringify(result,null,2)); if(!equal || observed.length!==419 || receipts.some(r=>r.stability_before!==0||r.stability_after!==0))process.exitCode=1;
NODE
